import re
from collections import Counter
import pandas as pd
r = pd.read_csv("reviews_text.csv")

def tokenize(text):
    return re.findall(r"[а-яё]+", text.lower())


def skipgram_pairs(tokens,window=2):
    return [(c,tokens[j]) for i,c in enumerate(tokens) for j in range(max(0,i-window),min(len(tokens),i+window+1)) if j!=i]
pairs=[p for t in r.text for p in skipgram_pairs(tokenize(t))]
n_pairs=len(pairs)
def top(w):
    return [c for c,n in Counter(b for a,b in pairs if a==w).most_common(3)]
top_courier=top("курьер");shared=set(top("дороговато"))&set(top("недорого"))
